#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<string> cards(n);
    for (string& card : cards) cin >> card;

    auto matches = [](const string& a, const string& b) {
        return a[0] == b[0] || a[1] == b[1];
    };

    queue<pair<int, string>> q;
    vector<unordered_set<string>> visited(n);

    string initial;
    for (int i = max(0, n - 3); i < n; ++i) {
        initial += cards[i];
    }

    q.push({n - 1, initial});
    visited[n - 1].insert(initial);

    auto addState = [&](int index, const string& state) {
        if (visited[index].insert(state).second) {
            q.push({index, state});
        }
    };

    while (!q.empty()) {
        auto [i, state] = q.front();
        q.pop();

        if (i == 0) {
            cout << "YES";
            return 0;
        }

        int pileCount = i + 1;
        int cardCount = static_cast<int>(state.size()) / 2;
        string rightmost = state.substr((cardCount - 1) * 2, 2);

        if (pileCount >= 4 && matches(rightmost, cards[i - 3])) {
            string next = rightmost + state.substr(0, 4);
            addState(i - 1, next);
        }

        string adjacent = state.substr((cardCount - 2) * 2, 2);
        if (matches(rightmost, adjacent)) {
            string next;

            if (pileCount == 2) {
                next = rightmost;
            } else if (pileCount == 3) {
                next = state.substr(0, 2) + rightmost;
            } else {
                next = cards[i - 3] + state.substr(0, 2) + rightmost;
            }

            addState(i - 1, next);
        }
    }

    cout << "NO";
    return 0;
}

