#include <bits/stdc++.h>
using namespace std;

using u64 = uint64_t;
using Card = uint16_t;

bool matches(Card a, Card b) {
    return (a >> 8) == (b >> 8) || (a & 255) == (b & 255);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Card> cards(n);
    for (int i = 0; i < n; ++i) {
        string s;
        cin >> s;
        cards[i] = (Card(static_cast<unsigned char>(s[0])) << 8) |
                   Card(static_cast<unsigned char>(s[1]));
    }

    if (n == 0) {
        cout << "NO";
        return 0;
    }

    u64 initial = 0;
    for (int i = max(0, n - 3); i < n; ++i)
        initial = (initial << 16) | cards[i];

    unordered_set<u64> states;
    states.insert(initial);

    for (int i = n - 1; i > 0 && !states.empty(); --i) {
        unordered_set<u64> nextStates;

        for (u64 state : states) {
            Card current = Card(state & 0xFFFF);
            Card previous = Card((state >> 16) & 0xFFFF);

            if (matches(current, previous)) {
                u64 nextState;

                if (i >= 3) {
                    Card first = Card((state >> 32) & 0xFFFF);
                    nextState = (u64(cards[i - 3]) << 32) |
                                (u64(first) << 16) |
                                current;
                } else if (i == 2) {
                    Card first = Card((state >> 32) & 0xFFFF);
                    nextState = (u64(first) << 16) | current;
                } else {
                    nextState = current;
                }

                nextStates.insert(nextState);
            }

            if (i >= 3 && matches(current, cards[i - 3])) {
                Card first = Card((state >> 32) & 0xFFFF);
                Card second = Card((state >> 16) & 0xFFFF);

                u64 nextState = (u64(current) << 32) |
                                (u64(first) << 16) |
                                second;

                nextStates.insert(nextState);
            }
        }

        states.swap(nextStates);
    }

    cout << (states.empty() ? "NO" : "YES");
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

bool matches(const string& a, const string& b) {
    return a[0] == b[0] || a[1] == b[1];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<string> cards(n);
    for (string& card : cards) cin >> card;

    if (n == 0) {
        cout << "NO";
        return 0;
    }

    string initial;
    for (int i = max(0, n - 3); i < n; ++i) {
        initial += cards[i];
    }

    unordered_set<string> current;
    current.insert(initial);

    for (int remaining = n; remaining > 1 && !current.empty(); --remaining) {
        unordered_set<string> next;

        for (const string& state : current) {
            const int length = static_cast<int>(state.size());
            const string top = state.substr(length - 2, 2);
            const string previous = state.substr(length - 4, 2);

            if (matches(top, previous)) {
                string newState;

                if (remaining >= 4) {
                    newState = cards[remaining - 4];
                    newState += state.substr(0, 2);
                    newState += top;
                } else if (remaining == 3) {
                    newState = state.substr(0, 2) + top;
                } else {
                    newState = top;
                }

                next.insert(newState);
            }

            if (remaining >= 4 && matches(top, cards[remaining - 4])) {
                string newState = top + state.substr(0, 4);
                next.insert(newState);
            }
        }

        current.swap(next);
    }

    cout << (current.empty() ? "NO" : "YES");
    return 0;
}

